pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement: minimizing this encourages Best-Fit behavior.
    let mut score = post_res;

    // Penalty for creating 'dead space' that is too small to fit common items (e.g., < 15).
    // This penalty scales non-linearly with the progress of the stream.
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res) * (1.0 + 2.0 * progress);
    }

    // Lookahead coupling: if the next item is large, penalize small residuals that would force
    // an early new bin later.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post_res < next_item {
            score += (next_item - post_res) * 1.5;
        }
    }

    // Reward bins that maintain a residual close to the global mean, 
    // encouraging a uniform distribution of fill levels across bins.
    let dev_from_mean = (post_res - mean_residual).abs();
    score += dev_from_mean * 0.5 * (1.0 - progress);

    // If this is a new bin (residual == capacity), penalize opening it based on 
    // the number of existing bins that could have fit the current item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 25.0 * (1.0 - progress);

        // As the stream nears completion, heavily discourage opening new bins.
        score += (progress * 100.0);
    }

    score
}

