pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize creating very small, unusable gaps (dead space).
    // Gaps between 1 and 9 are often impossible to fill given the input range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If the next item can fit in the current post_residual, 
    // reward this bin to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global State: If we are near the end of the stream, prioritize aggressive consolidation.
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. New Bin Logic: Discourage opening a new bin unless the fit is very poor 
    // in existing bins (represented by high post_residual or high mean_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but decreases as current bins become crowded.
        score = 60.0 + (mean_residual * 0.5);
    } else {
        // 5. Fitting Pressure: If this is the only bin that can fit the item, 
        // prioritize it to avoid wasting a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Penalize bins that deviate too far from the mean residual to keep packing balanced.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for common items (e.g., < 20).
    // If post_residual is in the range [1, 19], it is highly likely to become unusable.
    if post_residual > 0 && post_residual < 20 {
        score += 50.0 + (20.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If the next item is large, prioritize bins that can accommodate it.
    // If the current bin cannot fit the next item anyway, we prefer to keep it tight.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that leave a perfect fit for the next item (mod 10 alignment).
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.1;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that fits the current item, 
    // we should prioritize it unless it creates a terrible fragment.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 40.0;
    }

    // 4. Global Density Control: Favor filling up bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is dynamic: higher as we approach the end.
        score += 60.0 + (progress * 40.0);
    }

    // 5. Residual Balancing: Penalize bins that deviate significantly from the mean residual.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}
